const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const dateStart = '2018-02-03';
    const dateEnd = '2018-02-04'; // A one-day period

    // Get country boundaries
    const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
    const vietnamGeom = countries.filter(ee.Filter.eq('country_na', 'Vietnam')).geometry();
    const myanmarGeom = countries.filter(ee.Filter.eq('country_na', 'Myanmar')).geometry();

    // 2. Data Acquisition & Check
    const firms = ee.ImageCollection('FIRMS').filterDate(dateStart, dateEnd);

    // Check if there is any data for the selected day globally
    const firmsSize = firms.size().getInfo();
    if (firmsSize === 0) {
        console.log('No fire data found for the specified date globally.');
        console.log('A');
        return;
    }

    // 3. Processing: Filter fire detections for each country
    const vietnamFires = firms.select('T21').map(function(image) {
        return image.gt(0); // Create a binary image of fire detections
    }).mosaic().clip(vietnamGeom);

    const myanmarFires = firms.select('T21').map(function(image) {
        return image.gt(0);
    }).mosaic().clip(myanmarGeom);

    // 4. Calculation: Count the number of fire pixels in each country
    const scale = 1000; // FIRMS data is at 1km resolution

    const vietnamCountDict = vietnamFires.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: vietnamGeom,
        scale: scale,
        maxPixels: 1e9
    });

    const myanmarCountDict = myanmarFires.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: myanmarGeom,
        scale: scale,
        maxPixels: 1e9
    });

    // Use .evaluate to run computations in parallel
    const [vietnamResult, myanmarResult] = await new Promise((resolve, reject) => {
        ee.Dictionary.fromLists(['vietnam', 'myanmar'], [vietnamCountDict, myanmarCountDict]).evaluate((result, error) => {
            if (error) {
                reject(error);
            } else {
                resolve([result.vietnam, result.myanmar]);
            }
        });
    });

    const vietnamFireCount = vietnamResult.T21;
    const myanmarFireCount = myanmarResult.T21;

    // 5. Validation & Final Answer
    if (vietnamFireCount === null || myanmarFireCount === null) {
        console.log('Calculation failed: one or both results are null.');
        console.log('C3');
        return;
    }

    console.log(`Date: ${dateStart}`);
    console.log(`Vietnam active fire pixels: ${vietnamFireCount}`);
    console.log(`Myanmar active fire pixels: ${myanmarFireCount}`);

    if (vietnamFireCount > myanmarFireCount) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(e);
    console.log('D');
